--[混淆]
(function()
    local b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local b64 = ''
    local decoded = {}
    local padding = 0
    
    if b64:sub(-1) == '=' then padding = 1 end
    if b64:sub(-2, -2) == '=' then padding = 2 end
    
    for i = 1, #b64 - padding, 4 do
        local a = (string.find(b64chars, b64:sub(i, i), 1, true) or 1) - 1
        local b = (string.find(b64chars, b64:sub(i+1, i+1), 1, true) or 1) - 1
        local c = (string.find(b64chars, b64:sub(i+2, i+2), 1, true) or 1) - 1
        local d = (string.find(b64chars, b64:sub(i+3, i+3), 1, true) or 1) - 1
        
        local n = a * 262144 + b * 4096 + c * 64 + d
        
        decoded[#decoded + 1] = string.char(math.floor(n / 65536) % 256)
        decoded[#decoded + 1] = string.char(math.floor(n / 256) % 256)
        decoded[#decoded + 1] = string.char(n % 256)
    end
    
    if padding == 1 then
        local a = (string.find(b64chars, b64:sub(-4, -4), 1, true) or 1) - 1
        local b = (string.find(b64chars, b64:sub(-3, -3), 1, true) or 1) - 1
        local c = (string.find(b64chars, b64:sub(-2, -2), 1, true) or 1) - 1
        local n = a * 262144 + b * 4096 + c * 64
        decoded[#decoded + 1] = string.char(math.floor(n / 65536) % 256)
        decoded[#decoded + 1] = string.char(math.floor(n / 256) % 256)
    elseif padding == 2 then
        local a = (string.find(b64chars, b64:sub(-4, -4), 1, true) or 1) - 1
        local b = (string.find(b64chars, b64:sub(-3, -3), 1, true) or 1) - 1
        local n = a * 262144 + b * 4096
        decoded[#decoded + 1] = string.char(math.floor(n / 65536) % 256)
    end
    
    local code = table.concat(decoded)
    local loader = (loadstring or load)
    local success, func = pcall(loader, code)
    if success and type(func) == 'function' then
        func()
    end
end)()
